CREATE TABLE job_stage_times(job_id TEXT NOT NULL REFERENCES jobs(job_id),stage TEXT NOT NULL,ended_at REAL NOT NULL,PRIMARY KEY(job_id,stage));
CREATE TRIGGER job_stage_ended AFTER UPDATE OF checkpoint ON jobs WHEN json_valid(OLD.checkpoint) AND json_valid(NEW.checkpoint) AND json_extract(OLD.checkpoint,'$.stage') IN ('COLLECT','PROCESS','EMBED','INDEX') AND json_extract(NEW.checkpoint,'$.stage') IS NOT json_extract(OLD.checkpoint,'$.stage') BEGIN INSERT OR REPLACE INTO job_stage_times(job_id,stage,ended_at) VALUES(NEW.job_id,json_extract(OLD.checkpoint,'$.stage'),NEW.updated_at); END;
